#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define INDEX_BITS 11
#define INDEX_MASK ((1ULL << INDEX_BITS) - 1ULL)
#define SHIFT (2 * INDEX_BITS)

static int compare_u64_desc(const void *a, const void *b) {
    uint64_t x = *(const uint64_t *)a;
    uint64_t y = *(const uint64_t *)b;
    return (x < y) - (x > y);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *x = malloc((size_t)(n + 1) * sizeof(int));
    int *y = malloc((size_t)(n + 1) * sizeof(int));
    if (x == NULL || y == NULL) {
        free(x);
        free(y);
        return 0;
    }

    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &x[i], &y[i]);
    }

    size_t edge_count = (size_t)n * (size_t)n;
    uint64_t *edges = malloc(edge_count * sizeof(uint64_t));
    if (edges == NULL) {
        free(x);
        free(y);
        return 0;
    }

    size_t count = 0;

    for (int v = 1; v <= n; v++) {
        long long dx = x[v];
        long long dy = y[v];
        uint64_t distance = (uint64_t)(dx * dx + dy * dy);
        edges[count++] = (distance << SHIFT) | (uint64_t)v;
    }

    for (int u = 1; u <= n; u++) {
        for (int v = 1; v <= n; v++) {
            if (u == v) {
                continue;
            }
            long long dx = (long long)x[u] - x[v];
            long long dy = (long long)y[u] - y[v];
            uint64_t distance = (uint64_t)(dx * dx + dy * dy);
            edges[count++] = (distance << SHIFT) |
                             ((uint64_t)u << INDEX_BITS) |
                             (uint64_t)v;
        }
    }

    qsort(edges, count, sizeof(uint64_t), compare_u64_desc);

    int *best = calloc((size_t)n + 1, sizeof(int));
    int *pending = malloc(((size_t)n + 1) * sizeof(int));
    int *stamp = calloc((size_t)n + 1, sizeof(int));
    int *touched = malloc(((size_t)n + 1) * sizeof(int));

    if (best == NULL || pending == NULL || stamp == NULL || touched == NULL) {
        free(x);
        free(y);
        free(edges);
        free(best);
        free(pending);
        free(stamp);
        free(touched);
        return 0;
    }

    int answer = 0;
    int generation = 0;

    for (size_t begin = 0; begin < count;) {
        uint64_t distance = edges[begin] >> SHIFT;
        size_t end = begin + 1;
        while (end < count && (edges[end] >> SHIFT) == distance) {
            end++;
        }

        generation++;
        int touched_count = 0;

        for (size_t i = begin; i < end; i++) {
            uint64_t edge = edges[i];
            int u = (int)((edge >> INDEX_BITS) & INDEX_MASK);
            int v = (int)(edge & INDEX_MASK);
            int candidate = best[u] + 1;

            if (stamp[v] != generation) {
                stamp[v] = generation;
                pending[v] = candidate;
                touched[touched_count++] = v;
            } else if (candidate > pending[v]) {
                pending[v] = candidate;
            }
        }

        for (int i = 0; i < touched_count; i++) {
            int v = touched[i];
            if (pending[v] > best[v]) {
                best[v] = pending[v];
                if (best[v] > answer) {
                    answer = best[v];
                }
            }
        }

        begin = end;
    }

    printf("%d\n", answer);

    free(x);
    free(y);
    free(edges);
    free(best);
    free(pending);
    free(stamp);
    free(touched);
    return 0;
}
```

